export interface ConnectorConfig {
  airtableApiKey: string;
  airtableBaseId: string;
  airtableTableIdOrName: string;
  fetch?: typeof fetch;
}

export interface ShopifyOrderPaidWebhook {
  id: string;
  label: string;
  currency: string;
  totals: Array<{
    type: string;
    display_text: string;
    amount: number;
  }>;
  customer?: {
    email?: string;
  };
  email?: string;
  [key: string]: unknown;
}

export interface HandleResult {
  recordId: string;
  createdTime: string;
}

function getCustomerEmail(payload: ShopifyOrderPaidWebhook): string {
  if (payload.customer?.email) return payload.customer.email;
  if (payload.email) return payload.email;
  return 'unknown@example.com';
}

function getTotalAmount(payload: ShopifyOrderPaidWebhook): number {
  const total = payload.totals?.find((t) => t.type === 'total');
  if (!total || typeof total.amount !== 'number') {
    throw new Error('Missing or invalid total amount in payload totals');
  }
  return total.amount;
}

export async function handle(
  payload: ShopifyOrderPaidWebhook,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.label) {
    throw new Error('Missing required field: label (order number)');
  }
  if (!payload.totals || !Array.isArray(payload.totals)) {
    throw new Error('Missing required field: totals array');
  }

  const orderNumber = payload.label;
  const totalCents = getTotalAmount(payload);
  const totalDollars = totalCents / 100;
  const customerEmail = getCustomerEmail(payload);

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableIdOrName}`;
  const body = {
    records: [
      {
        fields: {
          'Order Number': orderNumber,
          'Customer Email': customerEmail,
          Total: totalDollars,
        },
      },
    ],
  };

  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at ${url}`);
  }

  const data = (await response.json()) as {
    records: Array<{ id: string; createdTime: string }>;
  };

  if (!data.records || data.records.length === 0) {
    throw new Error('Airtable response missing created record');
  }

  return {
    recordId: data.records[0].id,
    createdTime: data.records[0].createdTime,
  };
}

